      "ratt_alternativ": 2,
      "innehall": ["diskriminant", "antal reella rötter"],
      "losning": "$x = -1 \\pm \\sqrt{1 - 5} = -1 \\pm \\sqrt{-4}$. Uttrycket under rottecknet är negativt, alltså saknas reella lösningar.",
      "bedomning": "+1 E för rätt alternativ."
    },
    {
      "del": null,
      "formaga": "P",
      "typ": "rutin",
      "poang": [2, 0, 0],
      "text": "Lös ekvationen $x^2 - 8x + 12 = 0$. Endast svar krävs.",
      "notis": "Kontrollera dina rötter genom insättning i ekvationen.",
      "innehall": ["pq-formeln"],
      "losning": "$x = 4 \\pm \\sqrt{16 - 12} = 4 \\pm 2$, alltså $x_1 = 6$ och $x_2 = 2$.",
