      "text": "I ekvationen $x^2 - 6x + c = 0$ är $c$ ett tal som kan varieras. Fullständiga lösningar krävs.",
      "innehall": ["diskriminant", "parameter", "kvadratkomplettering"],
      "deluppgifter": [
        {
          "formaga": "P",
          "typ": "redovisning",
          "poang": [1, 0, 0],
          "text": "Visa att ekvationen har exakt en lösning då $c = 9$ och ange lösningen. Svara exakt.",
          "losning": "$x = 3 \\pm \\sqrt{9 - 9} = 3$. Uttrycket under rottecknet är noll, alltså finns exakt en lösning, $x = 3$.",
          "bedomning": "+1 E för korrekt beräkning som visar att rotuttrycket blir noll och att $x = 3$."
        },
        {
          "formaga": "R",
          "typ": "resonemang",
          "poang": [0, 1, 0],
          "text": "Bestäm för vilka värden på $c$ ekvationen saknar reella lösningar. Motivera ditt svar.",
          "svarsrutor": {
            "etikett": "Saknar reella lösningar när",
            "val": ["$c < 9$", "$c = 9$", "$c > 9$"],
            "ratt": 2
